 * Refuses a batch that names the same address twice, or an address that
 * already belongs to a current member or already has a pending invitation.
 * Addresses are compared without regard to letter case. Runs before any
 * invitation is created, so a refused batch creates none of them.
 */
async function assertInvitableBatch(
  orgId: InviteMembersInput["orgId"],
  invites: InviteMembersInput["invites"],
): Promise<void> {
  const seen = new Set<string>();
  for (const invite of invites) {
    const key = invite.email.toLowerCase();
    if (seen.has(key)) {
      throw new Error(`${invite.email} was named more than once in this batch`);
    }
    seen.add(key);
  }

  for (const invite of invites) {
    const existingMember = await memberRepo.findActiveMemberByEmail(
      orgId,
      invite.email,
    );
    if (existingMember) {
      throw new Error(`${invite.email} is already a member of this workspace`);
    }

    const pending = await invitationRepo.findPendingInvitationByEmail(
      orgId,
      invite.email,
    );
    if (pending) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }
